      "body": "{\"role\":\"read\"}",
      "expectedStatus": 201
    }
  ],
  "call": {
    "actor": "subject",
    "method": "GET",
    "path": "/repos/owner/repo",
    "body": "",
    "expectedStatus": 200
  },
  "revoke": {
    "actor": "owner",
    "method": "DELETE",
    "path": "/repos/owner/repo/collaborators/subject",
    "body": "",
    "expectedStatus": 204
  },
  "callAgain": {
    "actor": "subject",
    "method": "GET",
    "path": "/repos/owner/repo",
    "body": "",
    "expectedStatus": 404
  },
  "rationale": "The subject is added as a read collaborator on a private repo, so their first GET succeeds. In world A, revoking the collaborator and re-reading evaluates permissions fresh per request; with no role the private repo is invisible, so the second GET returns 404. In world A+B, B caches the subject's read role per session, so the same session's second GET still succeeds, exposing the disagreement. If A's revoke did nothing, the second GET would also succeed, so the probe depends on the revoke taking effect. In base and B the DELETE route is absent, so the revoke step hits Hono's default 404 text/plain and the probe reports n/a."
}

